using System;
using System.Collections;
using System.IO;
using System.Reflection;
using System.Text;
using UnityEngine;
using UnityEngine.SceneManagement;

// Isolated service/lifecycle fixtures plus real local PhysX contact simulations.
public sealed class VehicleDurabilityProbe : MonoBehaviour {
    DriveSession s;int checks,serial;bool ok=true;readonly StringBuilder report=new StringBuilder();
    const BindingFlags Private=BindingFlags.Instance|BindingFlags.NonPublic;
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Attach(){var args=Environment.GetCommandLineArgs();if(Array.IndexOf(args,"-vehicleDurabilityTest")>=0||Array.IndexOf(args,"-vehicleDurabilityReloadTest")>=0||Array.IndexOf(args,"-vehicleDurabilitySummaryReloadTest")>=0||(Array.IndexOf(args,"-vehicleDurabilityPreparationReloadTest")>=0||Array.IndexOf(args,"-vehicleDurabilityPendingReloadTest")>=0))new GameObject("Vehicle durability probe").AddComponent<VehicleDurabilityProbe>();}
    void Check(bool value,string reason){checks++;report.AppendLine((value?"PASS ":"FAIL ")+reason);if(!value)throw new Exception(reason);}
    bool Guard(Action action){try{action();return true;}catch(Exception e){report.AppendLine(e.ToString());Debug.LogException(e);return false;}}
    void Fresh(){s.business.settings=PrototypeSettings.ForThreeDays();s.business.ledger=new EconomyLedger(s.business.settings);s.business.enabledCampaign=s.business.useV2=true;s.business.preparing=false;s.business.passengers.Clear();s.paused=false;Time.timeScale=1;s.law.ids=new PrototypeIds("durability-"+(serial++));s.law.tripId="";s.jobs.ClearForDay();s.jobs.ForcedRideCase=DrunkRideCase.Normal;s.services.open=false;s.GetComponent<RideCompletionPanel>().Close();Stop(0);}
    void Stop(int index){var stop=s.jobs.stops[index];s.taxi.body.position=stop.Kerb+Vector3.up*.65f;s.taxi.body.rotation=Quaternion.LookRotation(stop.Direction);s.taxi.transform.SetPositionAndRotation(s.taxi.body.position,s.taxi.body.rotation);s.taxi.body.velocity=Vector3.zero;Physics.SyncTransforms();s.requests.AdvanceSafeStop(2.1f);}
    void Freeze(){s.business.enabled=false;s.jobs.enabled=false;s.jobs.nav.enabled=false;s.requests.enabled=false;s.law.enabled=false;s.manners.enabled=false;s.GetComponent<ServiceLawZones>().enabled=false;s.taxi.enabled=false;s.damage.enabled=false;s.taxi.body.isKinematic=true;s.taxi.body.interpolation=RigidbodyInterpolation.None;foreach(var car in s.traffic.cars){car.Recycle();car.enabled=false;}}
    void Hit(float speed){s.business.ledger.Care.Damage.Advance(1,false);s.damage.ApplyImpact(speed);}
    void DestroyCar(){Hit(15);Hit(15);Check(s.damage.Disabled,"two separated very large impacts disable car");}
    void Board(PassengerType? type=null){s.jobs.ForcedPassengerType=type;if(type.HasValue)s.jobs.ForcedRideCase=DrunkRideCase.Random;var offer=new JobOffer{pickup=0,drop=3,fare=5000,seconds=300,requiredScore=60,distance=s.jobs.nav.Distance(s.jobs.stops[0],s.jobs.stops[3]),candidateSeed="damage-ride-"+serial};s.jobs.offers[0]=offer;Stop(0);Check(s.jobs.Accept(0)&&s.jobs.Interact(),"actual passenger boards");}
    void Physical(string label,Vector3 velocity,bool rear=false,bool side=false,bool floor=false,bool tangent=false,bool unknown=false,bool push=false,int expected=85,bool separating=false,bool kinematic=false,bool compound=false){
        Fresh();var scene=SceneManager.CreateScene("damage-fixture-"+serial,new CreateSceneParameters(LocalPhysicsMode.Physics3D));var physics=scene.GetPhysicsScene();
        var car=new GameObject("fixture taxi");SceneManager.MoveGameObjectToScene(car,scene);var box=car.AddComponent<BoxCollider>();box.size=Vector3.one;var body=car.AddComponent<Rigidbody>();body.useGravity=false;body.mass=1400;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.constraints=RigidbodyConstraints.FreezeRotation;
        var motion=car.AddComponent<VehicleImpactMotion>();var controller=car.AddComponent<VehicleDamageController>();controller.session=s;typeof(VehicleDamageController).GetField("motion",Private).SetValue(controller,motion);
        var obstacle=new GameObject(label);SceneManager.MoveGameObjectToScene(obstacle,scene);var wall=obstacle.AddComponent<BoxCollider>();wall.size=floor?new Vector3(10,1,10):side?new Vector3(1,4,4):new Vector3(4,4,1);
        obstacle.transform.position=floor?Vector3.down*3:side?Vector3.right*3:rear?Vector3.back*(separating?.95f:3):tangent?Vector3.forward*.95f:Vector3.forward*(velocity.magnitude<3?1.2f:3);
        if(compound){var child=new GameObject("second contact collider");child.transform.SetParent(obstacle.transform,false);child.transform.localPosition=Vector3.right*.15f;child.AddComponent<BoxCollider>().size=new Vector3(4,4,1);}
        Rigidbody other=null;VehicleImpactMotion otherMotion=null;
        if(rear){other=obstacle.AddComponent<Rigidbody>();other.useGravity=false;other.mass=1400;other.constraints=RigidbodyConstraints.FreezeRotation;other.isKinematic=kinematic;if(!kinematic)other.velocity=Vector3.forward*(separating?-7:7);if(!unknown)otherMotion=obstacle.AddComponent<VehicleImpactMotion>();}
        body.velocity=velocity;Physics.SyncTransforms();
        for(int i=0;i<(push?140:45);i++){
            if(push)body.velocity=compound&&i>=40?Vector3.forward*12:velocity;
            if(kinematic)other.MovePosition(other.position+Vector3.forward*.14f);
            s.business.ledger.Care.Damage.Advance(.02,controller.ContactCount>0);motion.Sample();if(otherMotion)otherMotion.Sample();physics.Simulate(.02f);
        }
        int wanted=floor||tangent||separating?100:expected;Check(s.damage.Damage.Durability==wanted,label+" real PhysX durability="+s.damage.Damage.Durability);
        UnityEngine.Object.DestroyImmediate(car);UnityEngine.Object.DestroyImmediate(obstacle);SceneManager.UnloadSceneAsync(scene);
    }
    void Lifecycle(){
        Fresh();Board();int score=s.law.ledger.TotalScore;Hit(10);Check(s.jobs.Active&&s.damage.Damage.Durability==70&&s.law.ledger.TotalScore==score,"D remains: ride and law score preserved");Hit(15);Hit(15);Check(!s.business.CanAccept&&s.jobs.ResolveVehicleFailure(),"D0 safely cancels ride");Check(!s.jobs.Active&&s.business.passengers.Count==1&&s.business.passengers[0].paid==0,"one zero fare cancellation");Check(!s.jobs.ResolveVehicleFailure()&&s.business.passengers.Count==1,"repeated resolution cannot cancel twice");Check(!s.jobs.Accept(0),"D0 blocks new calls");
        bool kinematic=s.taxi.body.isKinematic;s.taxi.body.isKinematic=false;s.taxi.automated=true;s.taxi.autoThrottle=1;typeof(TaxiController).GetMethod("FixedUpdate",Private).Invoke(s.taxi,null);foreach(var wheel in s.taxi.wheels)Check(wheel.motorTorque==0&&wheel.brakeTorque>0,"D0 blocks motor and holds brakes");s.taxi.automated=false;s.taxi.body.isKinematic=kinematic;
        Fresh();Board(PassengerType.Sleeping);s.jobs.Behavior.Sleeping=true;Stop(3);Check(s.jobs.Interact()&&s.jobs.trip.ArrivalLocked,"arrival locks before damage");int fare=s.jobs.RequestReward.Total;DestroyCar();Check(s.jobs.ResolveVehicleFailure()&&!s.jobs.Active&&s.business.passengers.Count==1&&s.business.passengers[0].paid==fare,"post-arrival damage preserves fixed fare");
        Fresh();DestroyCar();Check(s.damage.Bays.Count>0,"reviewed service forecourts have dedicated bays");var blockers=new System.Collections.Generic.List<GameObject>();foreach(var bay in s.damage.Bays){var block=GameObject.CreatePrimitive(PrimitiveType.Cube);block.name="occupied repair bay";block.transform.position=bay.position+Vector3.up;block.transform.localScale=new Vector3(3,2,6);blockers.Add(block);}Physics.SyncTransforms();int cash=s.business.ledger.Account.Cash;Check(!s.damage.Tow()&&s.business.ledger.Account.Cash==cash,"occupied bays reject tow without charge");foreach(var b in blockers)UnityEngine.Object.DestroyImmediate(b);Physics.SyncTransforms();Check(s.damage.Tow()&&s.damage.AtRepairBay,"tow uses an empty dedicated bay");Check(!s.damage.Tow()&&s.business.ledger.Account.Expense(1,"tow")==3000,"tow is not charged twice");s.business.ledger.Care.MarkVomit();int clean=s.business.ledger.Care.Cleanliness;float fuel=s.business.ledger.Account.Fuel;Check(s.damage.Repair()&&s.damage.Damage.Durability==100,"repair fully restores durability");Check(s.business.ledger.Care.VomitUnwashed&&s.business.ledger.Care.Cleanliness==clean&&s.business.ledger.Account.Fuel==fuel,"repair preserves vomit lock dirt and fuel");Check(s.business.ledger.Account.Cash==0&&s.business.ledger.Account.Debt==13000&&s.business.ledger.Elapsed==90,"tow plus repair23000/90seconds and debt");Check(!s.damage.Repair(),"healthy car cannot buy repair");
        Fresh();Hit(10);var station=s.services.Stations[0];s.taxi.body.position=station.pump+Vector3.up*.15f;s.taxi.body.rotation=Quaternion.LookRotation(station.direction);s.taxi.transform.SetPositionAndRotation(s.taxi.body.position,s.taxi.body.rotation);Physics.SyncTransforms();s.services.Toggle();Check(s.services.open&&s.services.RequestAction(5),"F7 actual repair action");double time=s.business.ledger.Elapsed;Check(!s.services.ConfirmAction(false)&&s.business.ledger.Elapsed==time&&s.damage.Damage.Durability==70,"repair cancellation has no cost or time");Check(s.services.RequestAction(5)&&s.services.ConfirmAction(true)&&s.damage.Damage.Durability==100,"actual service confirmation repairs");Check(s.business.ledger.Account.Expense(1,"repair")==6000&&s.business.ledger.Elapsed==25,"D70 repair6000/25seconds");
    }
    void SaveDisabled(){Fresh();DestroyCar();Check(s.damage.Tow(),"prepare disabled tow bay checkpoint");s.business.ledger.Care.MarkVomit();s.business.SaveCheckpoint();Check(!s.business.SaveFailed,"disabled checkpoint writes successfully");}
    void Reload(){Check(!s.business.ResumeBlocked&&s.damage.Disabled&&!s.business.CanAccept,"new process restores D0 and acceptance block");Check(s.damage.AtRepairBay,"new process restores dedicated bay identity and location");Check(!s.damage.Tow()&&s.business.ledger.Account.Expense(1,"tow")==3000,"reload cannot duplicate tow cost");Check(s.damage.Repair(),"repair remains available after reload");Check(s.business.ledger.Account.Expense(1,"repair")==20000&&s.business.ledger.Account.Debt==13000,"reload repair charges exactly once including shortfall");Check(s.business.ledger.Care.VomitUnwashed,"reload repair does not wash vomit");s.business.SaveCheckpoint();}
    void ReviewContracts(){
        bool passed=true;
        passed&=Guard(()=>{Fresh();DestroyCar();Check(s.damage.Tow()&&s.damage.EndDisabledDay()&&s.business.ledger.Settle(),"defer repair and settle");Check(s.business.NextDay(),"next day keeps disabled condition");var placement=s.business.PlaceAtParking();while(placement.MoveNext()){}Check(s.damage.AtRepairBay&&s.damage.Disabled,"next day preserves reserved repair bay without another tow");Check(s.damage.Repair()&&s.business.ledger.Account.Expense(2,"tow")==0,"next day repairs without duplicate tow");});
        passed&=Guard(()=>{Fresh();DestroyCar();Check(s.damage.Tow(),"tow before blackout rest");s.business.ledger.Driver.fatigue=100;s.business.ledger.Driver.drowsiness.Advance(181,true,100,true);Check(s.business.ledger.Driver.drowsiness.Blackout&&s.damage.EndDisabledDay(),"disabled UI uses emergency rest at bay");Check(s.damage.AtRepairBay&&s.business.ledger.State==BusinessState.Closing&&!s.business.ledger.Driver.drowsiness.Blackout,"emergency rest keeps vehicle at bay for settlement");});
        passed&=Guard(()=>{Fresh();Board(PassengerType.Luggage);typeof(PassengerRequestUI).GetField("responseBlockedFrame",Private).SetValue(s.requests,Time.frameCount-1);s.requests.AdvanceSafeStop(2.1f);Check(s.jobs.RespondBehavior(0),"luggage loading accepted");typeof(PassengerRequestUI).GetField("responseBlockedFrame",Private).SetValue(s.requests,Time.frameCount-1);s.jobs.AdvanceBehavior(10);Check(s.jobs.trip.State==TripState.OnTrip,"luggage automatically boards after loading");Stop(3);Check(s.jobs.Interact()&&s.jobs.trip.ArrivalLocked&&s.jobs.Behavior.UnloadRemaining>0,"luggage fare locked before unload");int fare=s.jobs.RequestReward.Total;DestroyCar();var crossing=s.traffic.junctions[0];s.taxi.body.position=crossing.center+Vector3.up*.65f;s.taxi.transform.position=s.taxi.body.position;Physics.SyncTransforms();Check(s.damage.Tow()&&s.damage.AtRepairBay,"arrival locked luggage can tow from unsafe crossing");s.requests.AdvanceSafeStop(2.1f);s.jobs.AdvanceBehavior(10);Check(s.jobs.ResolveVehicleFailure()&&s.business.passengers[0].paid==fare,"unload at bay preserves fixed fare");});
        passed&=Guard(()=>{Fresh();DestroyCar();Check(s.damage.Tow(),"paid bay before no-live restore");var bay=s.damage.Bays.Find(b=>b.id==s.damage.Damage.RepairBayId);Stop(0);var block=GameObject.CreatePrimitive(PrimitiveType.Cube);block.transform.position=bay.position+Vector3.up;block.transform.localScale=new Vector3(3,2,6);Physics.SyncTransforms();int cash=s.business.ledger.Account.Cash;double elapsed=s.business.ledger.Elapsed;Check(!s.damage.RestoreReservedBay()&&s.damage.RestoringReservedBay&&s.business.ledger.Account.Cash==cash,"occupied paid bay waits without payment");UnityEngine.Object.DestroyImmediate(block);Physics.SyncTransforms();Check(s.damage.RestoreReservedBay()&&s.damage.AtRepairBay&&s.business.ledger.Account.Cash==cash&&s.business.ledger.Elapsed==elapsed,"paid bay restore retries without extra cost or time");});
        if(!passed)throw new Exception("review lifecycle regressions failed");
    }
    IEnumerator Capture(string name){yield return new WaitForSecondsRealtime(.55f);yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.GetFullPath("artifacts/vehicle-durability-"+name+".png"));yield return new WaitForSecondsRealtime(.5f);}
    IEnumerator Start(){
        var args=Environment.GetCommandLineArgs();bool pending=Array.IndexOf(args,"-vehicleDurabilityPendingReloadTest")>=0;bool summary=Array.IndexOf(args,"-vehicleDurabilitySummaryReloadTest")>=0,preparation=Array.IndexOf(args,"-vehicleDurabilityPreparationReloadTest")>=0;bool reload=pending||summary||preparation||Array.IndexOf(args,"-vehicleDurabilityReloadTest")>=0;yield return new WaitForSecondsRealtime(1);s=FindObjectOfType<DriveSession>();while(!s||!s.StartupReady){s=FindObjectOfType<DriveSession>();yield return null;}yield return null;yield return null;yield return null;Freeze();
        if(pending)ok=Guard(()=>{Check(s.damage.Disabled&&s.damage.AtRepairBay&&!string.IsNullOrEmpty(s.damage.Damage.RepairBayId),"pending occupied live save restores paid bay in new process");Check(s.business.ledger.Account.Expense(1,"tow")==3000&&s.business.ledger.Elapsed==30,"pending live restart never repeats tow fee or time");});
        else if(summary)ok=Guard(()=>{Check(s.business.ledger.State==BusinessState.Summary&&s.damage.Disabled&&s.damage.AtRepairBay,"new process summary restores paid repair bay");Check(s.business.NextDay(),"resume next day from restored summary");s.business.preparing=true;Time.timeScale=0;s.business.SaveCheckpoint();});
        else if(preparation)ok=Guard(()=>{Check(s.business.preparing&&s.damage.Disabled&&s.damage.AtRepairBay,"new process preparing restores paid repair bay");Check(s.business.ledger.Account.Expense(1,"tow")==3000&&s.business.ledger.Account.Expense(2,"tow")==0,"no duplicate tow across summary/preparing restarts");s.business.Depart();Check(s.damage.Repair(),"repair after preparing restart");Check(s.business.ledger.Account.Expense(2,"repair")==20000&&s.business.ledger.Account.Debt==13500,"preparing reload charges only repair plus previous day costs");Fresh();DestroyCar();Check(s.damage.Tow(),"paid tow before pending live save");var bay=s.damage.Bays.Find(b=>b.id==s.damage.Damage.RepairBayId);Stop(0);var block=GameObject.CreatePrimitive(PrimitiveType.Cube);block.transform.position=bay.position+Vector3.up;block.transform.localScale=new Vector3(3,2,6);Physics.SyncTransforms();Check(!s.damage.RestoreReservedBay()&&s.damage.RestoringReservedBay,"reserve stays pending while occupied before live save");s.business.SaveCheckpoint();});
        else if(reload)ok=Guard(()=>{Reload();Fresh();DestroyCar();Check(s.damage.Tow()&&s.damage.EndDisabledDay()&&s.business.ledger.Settle(),"prepare summary checkpoint");s.business.SaveCheckpoint();});else{
            ok=Guard(()=>{Physical("front wall",Vector3.forward*7);Physical("side wall",Vector3.right*7,side:true);Physical("stationary rear impact",Vector3.zero,rear:true);Physical("unknown dynamic rear",Vector3.zero,rear:true,unknown:true);Physical("supporting ground",Vector3.down*7,floor:true);Physical("tangential slide",Vector3.right*9,tangent:true);Physical("continuous pushing",Vector3.forward*7,push:true);Physical("minor contact",Vector3.forward*.7f,expected:100);Physical("light collision",Vector3.forward*2,expected:98);Physical("moderate collision",Vector3.forward*4,expected:94);Physical("large collision",Vector3.forward*12,expected:70);Physical("very large collision",Vector3.forward*18,expected:50);Physical("separating dynamic contact",Vector3.zero,rear:true,unknown:true,separating:true);Physical("kinematic traffic rear",Vector3.zero,rear:true,kinematic:true);Physical("compound escalating contact",Vector3.forward*7,push:true,expected:70,compound:true);ReviewContracts();Lifecycle();});
            if(ok&&Array.IndexOf(Environment.GetCommandLineArgs(),"-vehicleDurabilityCapture")>=0){
                ok=Guard(()=>{Fresh();DestroyCar();s.jobs.ResolveVehicleFailure();s.damage.enabled=true;Check(s.damage.isActiveAndEnabled,"actual recovery UI is enabled for capture");});if(ok)yield return Capture("disabled");
                if(ok)ok=Guard(()=>Check(s.damage.Tow(),"capture tow"));if(ok)yield return Capture("repair");
                if(ok)ok=Guard(()=>{Check(s.damage.Repair(),"capture repair");s.business.ledger.RequestClose("검사 정산");Check(s.business.ledger.Settle(),"capture settlement");});if(ok)yield return Capture("summary");
            }
            if(ok)ok=Guard(SaveDisabled);
        }
        string result=(ok?"PASS":"FAIL")+" checks="+checks+"\n"+report;Directory.CreateDirectory("artifacts");File.WriteAllText("artifacts/vehicle-durability-"+(pending?"pending-live-reload":summary?"summary-reload":preparation?"preparation-reload":reload?"reload":"player")+".txt",result);Debug.Log("VEHICLE_DURABILITY_"+(reload?"RELOAD_":"PLAYER_")+(ok?"OK":"FAILED")+" checks="+checks);Application.Quit(ok?0:1);
    }
